package dev.soundceiling.app;
import java.util.Arrays;
public final class PureLogicTest{public static void main(String[]a){testOutput();testPeak();testCurve();testDecision();testFrequency();testState();testLog();testDestination();System.out.println("PureLogicTest: PASS");}static void testOutput(){assertFalse(Arrays.stream(OutputDevicePriority.forSdk(29)).anyMatch(v->v==26),"API29 BLE");}static void testPeak(){assertNear(-4f,GainPlanner.dbfs(-20f,-2f,0f,-10f,-6f,true,1f).desiredGainDb,.001f,"ceiling");}static void testCurve(){VolumeCurveMath.ValidationResult r=VolumeCurveMath.validate(new float[16],0,15);assertTrue(r.fallbackUsed,"flat fallback");assertEquals("flat_or_single_finite",r.reason,"reason");ControlVolumeCurve c=new ControlVolumeCurve(0,15);assertEquals(5,c.capIndexFromPercent(35),"cap");}static void testDecision(){ControlVolumeCurve c=new ControlVolumeCurve(0,15);ControlDecision d=DecisionEngine.decide(DecisionEngine.Input.dbfs(10000,-13.9f,-3.7f,true,0,-18f,-3f,true,1f,35,false,SpeedPreset.BALANCED,0,0,0),c);assertEquals(5,d.rawDesiredIndex,"raw");assertTrue(d.requestedIndex>=1,"audible");assertTrue(d.safetyReason==ControlDecision.SafetyReason.AUDIBLE_FLOOR,"floor");}static void testFrequency(){float[] centers=FrequencyBandTracker.centerFrequencies();for(int w=0;w<centers.length;w++){short[] pcm=ToneSamples.sinePcm16(48000,500,centers[w],-6f,2);float[] l=new FrequencyBandTracker(48000,2).update(pcm,pcm.length);int strongest=0;for(int i=1;i<l.length;i++)if(l[i]>l[strongest])strongest=i;assertEquals(w,strongest,"band");}}static void testState(){float[] b={1,.8f,.6f,.4f,.2f};RuntimeState s=new RuntimeState.Builder().running(true).captureStatus(RuntimeState.CaptureStatus.RUNNING).controlActivity(RuntimeState.ControlActivity.MINIMUM_LIMIT).signalPresent(true).volume(1,15).bandLevels(b).message("Работает").build();b[0]=0;assertNear(1,s.bandLevels()[0],.001f,"copy");assertEquals("Media 1/15",StatusText.media(s),"media");}static void testLog(){ControlDecision d=DecisionEngine.decide(DecisionEngine.Input.dbfs(12345,-13.9f,-3.7f,true,0,-18f,-3f,true,1f,35,false,SpeedPreset.BALANCED,0,0,0),new ControlVolumeCurve(0,15)).withAppliedIndex(1);String l=LogFormatter.formatDecision(d);assertTrue(l.contains("raw=5"),"raw log");assertFalse(l.toLowerCase().contains("pcm"),"no pcm");}static void testDestination(){assertTrue(AppDestination.fromPreference("broken")==AppDestination.SIMPLE,"fallback");}static void assertTrue(boolean v,String m){if(!v)throw new AssertionError(m);}static void assertFalse(boolean v,String m){assertTrue(!v,m);}static void assertNear(float e,float a,float x,String m){if(Math.abs(e-a)>x)throw new AssertionError(m+":"+a);}static void assertEquals(int e,int a,String m){if(e!=a)throw new AssertionError(m+":"+a);}static void assertEquals(String e,String a,String m){if(!e.equals(a))throw new AssertionError(m+":"+a);}}
